            S(1, true, "很多中国人吃饭用筷子。", "Many Chinese people eat with chopsticks.", "两根筷子，夹菜扒饭。", "Two sticks, for picking up food and shovelling rice."),
            S(1, true, "下雪天要穿厚衣服。", "You wear thick clothes on a snowy day.", "不穿秋裤，妈会担心。", "Skip the long johns and Mum will worry."),
            S(2, true, "蚂蚁能搬动比自己重的东西。", "An ant can carry things heavier than itself.", "蚂蚁能搬起自己体重好几倍的东西。", "An ant can lift several times its own weight."),
            S(2, true, "章鱼有八条腕足。", "An octopus has eight arms.", "「章鱼」英文 octopus，octo 就是八。", "Octo in octopus means eight."),
            S(2, true, "骆驼可以很多天不喝水。", "A camel can go for days without drinking.", "所以叫「沙漠之舟」。", "That is why it is called the ship of the desert."),
            S(2, true, "大多数西瓜切开是红瓤的。", "Most watermelons are red inside.", "也有黄瓤的，但红瓤最常见。", "Yellow ones exist, but red is most common."),
            S(2, true, "电脑键盘上有空格键。", "A computer keyboard has a space bar.", "最长的那个键。", "The longest key on it."),
            S(2, true, "冰箱的冷冻室比冷藏室更冷。", "A fridge's freezer is colder than the fridge part.", "冷冻室零下十几度，冷藏室几度。", "The freezer is well below zero; the fridge is a few degrees above."),
            S(2, true, "熬夜之后，第二天容易犯困。", "After staying up late, you get sleepy the next day.", "说的就是你。", "Yes, you."),
            S(2, true, "秋天很多树的叶子会变黄。", "In autumn, many trees' leaves turn yellow.", "银杏一到秋天就黄了。", "Ginkgo trees turn gold every autumn."),
            S(2, true, "仙人掌在很干的地方也能活。", "A cactus can live somewhere very dry.", "它把水存在厚厚的茎里。", "It stores water in its thick stem."),
            S(3, true, "鲸鱼不是鱼，是哺乳动物。", "A whale is not a fish; it is a mammal.", "鲸鱼用肺呼吸，还给小鲸鱼喂奶。", "Whales breathe with lungs and feed their young milk."),
            S(3, true, "蝙蝠是会飞的哺乳动物。", "A bat is a mammal that flies.", "蝙蝠不是鸟，它是胎生的。", "Bats are not birds; they give birth to live young."),
            S(3, true, "用放大镜可以把阳光聚成一个很烫的小点。", "A magnifying glass can focus sunlight into a hot little spot.", "小时候都拿它烧过纸。", "Every kid has burned paper with one."),
            S(3, true, "一公斤棉花和一公斤铁一样重。", "A kilogram of cotton weighs the same as a kilogram of iron.", "都是一公斤，只是棉花体积大得多。", "Both are a kilogram; the cotton just takes up far more room."),
            S(3, true, "早上的影子比中午的长。", "Shadows are longer in the morning than at noon.", "太阳越低，影子越长。", "The lower the sun, the longer the shadow."),
            S(3, true, "电脑死机了，重启经常能解决。", "When a computer freezes, restarting often fixes it.", "重启试试，十个问题能好七个。", "Try a restart: it fixes most things."),
            S(3, true, "蚯蚓身体里没有骨头。", "An earthworm has no bones.", "它是软体的，靠肌肉一伸一缩地爬。", "It is soft all through and crawls by stretching and squeezing."),

            // ───────────── 生活里的常识 · 否（25） ─────────────
            S(1, false, "鸭子会说普通话。", "Ducks speak Mandarin.", "鸭子只会嘎嘎叫。", "Ducks only quack."),
            S(1, false, "冰淇淋是用石头做的。", "Ice cream is made of stone.", "冰淇淋是奶和糖冻出来的。", "Ice cream is frozen milk and sugar."),
            S(1, false, "狗有五条腿。", "Dogs have five legs.", "狗有四条腿。", "Dogs have four legs."),
            S(1, false, "鸡蛋是方的。", "Eggs are square.", "鸡蛋是椭圆的。", "Eggs are oval."),
            S(1, false, "鱼会骑自行车。", "Fish ride bicycles.", "鱼连腿都没有。", "Fish do not even have legs."),
            S(1, false, "柠檬是甜的。", "Lemons are sweet.", "柠檬是酸的。", "Lemons are sour."),
            S(1, false, "牙膏可以当饭吃。", "You can eat toothpaste as a meal.", "牙膏刷完要吐掉。", "You spit toothpaste out after brushing."),
            S(1, false, "下雨的时候，天上掉下来的是糖。", "When it rains, sugar falls from the sky.", "掉下来的是水。", "It is water that falls."),
            S(1, false, "刚从冰箱拿出来的冰棍是热的。", "An ice lolly straight from the freezer is hot.", "冰棍是冰的。", "An ice lolly is cold."),
            S(2, false, "蚊子是吃竹子长大的。", "Mosquitoes grow up eating bamboo.", "吃竹子的是熊猫。蚊子……吃你。", "Pandas eat bamboo. Mosquitoes eat… you."),
            S(2, false, "西瓜长在树上。", "Watermelons grow on trees.", "西瓜长在地上的藤蔓上。", "Watermelons grow on vines along the ground."),
            S(2, false, "冰箱是用来把东西加热的。", "A fridge is for heating food up.", "冰箱是让东西变凉的。", "A fridge keeps things cold."),
            S(2, false, "蜗牛跑得比兔子快。", "A snail runs faster than a rabbit.", "蜗牛慢得出名。", "Snails are famously slow."),
            S(2, false, "一只蚂蚁比一头大象重。", "An ant weighs more than an elephant.", "大象有好几吨，蚂蚁不到一克。", "An elephant weighs tonnes; an ant, less than a gram."),
            S(2, false, "仙人掌要每天泡在水里才能活。", "A cactus has to sit in water every day to live.", "仙人掌怕涝，水浇多了会烂根。", "Too much water rots a cactus's roots."),
            S(2, false, "文件扔进回收站，就彻底删掉了。", "A file in the Recycle Bin is gone for good.", "回收站里还能还原，清空了才算删。", "You can restore it until you empty the bin."),
            S(2, false, "用手机打电话不需要信号。", "A mobile phone needs no signal to make a call.", "没信号就打不出去。", "No signal, no call."),
            S(2, false, "企鹅住在沙漠里。", "Penguins live in the desert.", "企鹅大多住在南极一带，冷得很。", "Most penguins live around the Antarctic, where it is freezing."),
            S(3, false, "骆驼的驼峰里装的是水。", "A camel's hump is full of water.", "驼峰里存的是脂肪，饿了能顶一阵。", "The hump stores fat, which keeps it going when food is short."),
            S(3, false, "鲸鱼是用鳃呼吸的鱼。", "A whale is a fish that breathes with gills.", "鲸鱼用肺呼吸，要浮上水面换气。", "Whales breathe with lungs and surface for air."),
            S(3, false, "蝙蝠是一种鸟。", "A bat is a kind of bird.", "蝙蝠是哺乳动物，不下蛋。", "Bats are mammals and do not lay eggs."),
            S(3, false, "一公斤铁比一公斤棉花重。", "A kilogram of iron is heavier than a kilogram of cotton.", "都是一公斤，一样重。", "Both are a kilogram: the same weight."),
            S(3, false, "中午的影子是一天里最长的。", "Noon shadows are the longest of the day.", "中午太阳最高，影子最短。", "At noon the sun is highest and shadows are shortest."),
            S(3, false, "人的大脑平时只用了百分之十。", "People only use ten percent of their brains.", "这是谣言，大脑各个部分都在工作。", "A myth: every part of the brain does work."),
            S(3, false, "电脑死机了，键盘敲得越用力好得越快。", "When a computer freezes, the harder you hit the keyboard the faster it recovers.", "敲坏的只会是键盘。", "The only thing you will break is the keyboard."),

            // ───────────── 2016 年 · 是 / 否成对（按游戏日期出现，不早于事件当天） ─────────────
            S(2, true, "2016 年是猴年。", "2016 is the Year of the Monkey.", "丙申猴年，二月八号春节开始。", "The Year of the Monkey began at Spring Festival, 8 February."),
            S(2, false, "2016 年是羊年。", "2016 is the Year of the Goat.", "羊年是 2015 年，今年是猴年。", "The Goat was 2015; this year is the Monkey."),
            S(2, true, "《太阳的后裔》的男主角是宋仲基。", "Song Joong-ki is the male lead of Descendants of the Sun.", "春天那阵，满屏都是「宋仲基老公」。", "This spring everyone was calling him their husband."),
            S(2, false, "《太阳的后裔》是一部国产武侠剧。", "Descendants of the Sun is a Chinese kung fu drama.", "是韩剧，讲军人和医生的爱情。", "It is a Korean drama about a soldier and a doctor."),
            S(2, true, "电影《美人鱼》是周星驰导演的。", "The film The Mermaid was directed by Stephen Chow.", "春节档上映，票房破了纪录。", "Released for Spring Festival, it broke box-office records."),
            S(2, false, "电影《美人鱼》是迪士尼的动画片。", "The Mermaid is a Disney cartoon.", "那是《小美人鱼》。今年这部是周星驰拍的真人电影。", "That is The Little Mermaid. This year's is Stephen Chow's live-action film."),
            S(2, true, "小李子今年终于拿到了奥斯卡影帝。", "Leonardo DiCaprio finally won the Best Actor Oscar this year.", "靠《荒野猎人》，陪跑了二十多年。", "For The Revenant, after more than twenty years of trying."),
            S(2, false, "小李子今年又没拿到奥斯卡。", "Leo missed out on the Oscar again this year.", "今年拿到了，网友都替他松了口气。", "He won this year, and the internet sighed with relief."),
            S(2, true, "王者荣耀是一款手机游戏。", "Honor of Kings is a mobile game.", "宿舍里五个人开黑。", "Five roommates queue up together."),
            S(2, false, "王者荣耀是一档电视选秀节目。", "Honor of Kings is a TV talent show.", "是手机上的推塔游戏。", "It is a tower-pushing game on your phone."),
            On(20160524, S(2, true, "守望先锋是暴雪出的游戏。", "Overwatch is a Blizzard game.", "五月底开服，网吧里人手一个源氏。", "Out since late May; every café has a Genji main.")),
            On(20160524, S(2, false, "守望先锋是一款种菜的手机游戏。", "Overwatch is a farming game for phones.", "是电脑上的六对六射击游戏。", "It is a six-versus-six shooter on PC.")),
            On(20160527, S(2, true, "GTX 1080 是英伟达的显卡。", "The GTX 1080 is an NVIDIA graphics card.", "五月底上市，四千九百九十九。", "On sale since late May for ¥4,999.")),
            On(20160527, S(2, false, "GTX 1080 是一台洗衣机。", "The GTX 1080 is a washing machine.", "是显卡。虽然风扇转起来也挺像。", "It is a graphics card, though the fan does sound like one.")),
            On(20160608, S(2, true, "电影《魔兽》是根据暴雪的游戏改编的。", "The film Warcraft is based on Blizzard's games.", "六月八号上映，为了部落！", "Out on 8 June. For the Horde!")),
            On(20160608, S(2, false, "电影《魔兽》是根据金庸小说改编的。", "The film Warcraft is based on a Jin Yong novel.", "金庸写的是武侠，没写过兽人。", "Jin Yong wrote martial-arts stories, not orcs.")),
            On(20160611, S(2, true, "2016 年欧洲杯在法国举办。", "Euro 2016 is held in France.", "看球得熬到凌晨三点。", "Watching means staying up until 3 a.m.")),
            On(20160611, S(2, false, "2016 年欧洲杯在中国举办。", "Euro 2016 is held in China.", "在法国，所以才要熬夜看。", "It is in France; that is why we stay up.")),
            On(20160701, S(2, true, "Win10 免费升级 7 月 29 日截止。", "The free Windows 10 upgrade ends on 29 July.", "右下角天天弹窗提醒。", "The tray pops up a reminder every day.")),
            On(20160701, S(2, false, "Win10 免费升级永远不会截止。", "The free Windows 10 upgrade never ends.", "7 月 29 日截止，之后要花钱。", "It ends on 29 July; after that you pay.")),
            On(20160707, S(3, true, "Pokémon GO 是要走出门去抓精灵的手机游戏。", "Pokémon GO is a phone game where you walk around catching Pokémon.", "外国人满大街抓皮卡丘。", "People abroad are roaming the streets for Pikachu.")),
            On(20160707, S(3, false, "Pokémon GO 在国内可以正常玩。", "Pokémon GO works normally in mainland China.", "国内锁区，只能看别人玩。", "It is region-locked here; we can only watch.")),
            On(20160725, S(2, true, "「葛优躺」说的是整个人瘫在沙发上。", "The Ge You slouch means sprawling all over the sofa.", "出自《我爱我家》里的葛优。", "From Ge You in the sitcom I Love My Family.")),
            On(20160725, S(2, false, "「葛优躺」是站着睡觉。", "The Ge You slouch is sleeping standing up.", "是瘫着，越瘫越像。", "It is slumping. The flatter the better.")),
            On(20160808, S(2, true, "傅园慧说自己「已经用了洪荒之力」。", "Fu Yuanhui said she had used her primal powers.", "里约游泳采访，表情包一夜刷屏。", "A Rio swimming interview, memes everywhere overnight.")),
            On(20160808, S(2, false, "「洪荒之力」是一种新出的洗衣粉。", "Primal powers is a new washing powder.", "是傅园慧采访时说的话。", "It is what Fu Yuanhui said in an interview.")),
            On(20160809, S(3, true, "孙杨在里约拿了 200 米自由泳金牌。", "Sun Yang won the 200 m freestyle gold in Rio.", "中国游泳队又一块金牌。", "Another gold for China's swimmers.")),
            On(20160809, S(3, false, "孙杨是中国女排的队员。", "Sun Yang plays for China's women's volleyball team.", "孙杨是游泳运动员。", "Sun Yang is a swimmer.")),
            On(20160814, S(3, true, "中国战队 Wings 拿了 TI6 冠军。", "The Chinese team Wings won TI6.", "Dota 2 世界赛，奖金九百多万美元。", "The Dota 2 world championship, over nine million dollars.")),
            On(20160814, S(3, false, "TI6 是一场围棋比赛。", "TI6 is a Go tournament.", "是 Dota 2 的世界赛。", "It is the Dota 2 world championship.")),
            On(20160815, S(2, true, "博尔特在里约又拿了百米冠军。", "Usain Bolt won the 100 m again in Rio.", "三届奥运百米金牌。", "Three Olympic 100 m golds in a row.")),
            On(20160815, S(2, false, "博尔特是游泳运动员。", "Usain Bolt is a swimmer.", "博尔特是短跑运动员。", "Bolt is a sprinter.")),
            On(20160830, S(2, true, "王健林说过「先定一个小目标，比方说我先挣它一个亿」。", "Wang Jianlin said, \"First set a small goal, like earning a hundred million.\"", "全网都在定小目标。", "Now everyone is setting small goals.")),
            On(20160830, S(2, false, "王健林的小目标是先挣一百块。", "Wang Jianlin's small goal is to earn a hundred yuan first.", "是一个亿。", "It was a hundred million.")),
            On(20160902, S(2, true, "阴阳师是网易出的手机游戏。", "Onmyoji is a NetEase mobile game.", "九月公测，人人都在抽 SSR。", "Out in September; everyone is pulling for SSRs.")),
            On(20160902, S(2, false, "阴阳师是一档电视选秀节目。", "Onmyoji is a TV talent show.", "是手机上的抽卡游戏。", "It is a card-drawing game on phones.")),
            On(20160908, S(2, true, "iPhone 7 取消了耳机插孔。", "The iPhone 7 dropped the headphone jack.", "要用转接头或者无线耳机。", "You need an adapter or wireless earbuds.")),
            On(20160908, S(2, false, "iPhone 7 多加了一个耳机孔。", "The iPhone 7 added a second headphone jack.", "是去掉了，一个都没有了。", "It removed the jack entirely.")),
            On(20161010, S(2, true, "「蓝瘦，香菇」的意思是「难受，想哭」。", "\"Lan shou, xiang gu\" means \"feeling sad, want to cry\".", "带口音的「难受想哭」，一夜之间火了。", "\"Sad, want to cry\" in a thick accent, viral overnight.")),
            On(20161010, S(2, false, "「蓝瘦香菇」是一种蓝色的蘑菇。", "Lan shou xiang gu is a blue mushroom.", "是「难受想哭」的谐音。", "It sounds like \"sad, want to cry\".")),
            On(20161013, S(3, true, "鲍勃·迪伦拿了今年的诺贝尔文学奖。", "Bob Dylan won this year's Nobel Prize in Literature.", "第一次颁给一位歌手。", "The first time it went to a songwriter.")),
            On(20161013, S(3, false, "今年的诺贝尔文学奖颁给了一位厨师。", "This year's Nobel Prize in Literature went to a chef.", "颁给了歌手鲍勃·迪伦。", "It went to the singer Bob Dylan.")),
            On(20161017, S(3, true, "神舟十一号载着两名航天员上了太空。", "Shenzhou-11 carried two astronauts into space.", "景海鹏和陈冬，要去天宫二号住一个月。", "Jing Haipeng and Chen Dong, off to live on Tiangong-2 for a month.")),
            On(20161017, S(3, false, "神舟十一号是一列高铁。", "Shenzhou-11 is a high-speed train.", "是载人飞船。", "It is a crewed spacecraft.")),
            On(20161112, S(2, true, "今年双十一一天卖了一千多亿元。", "This Singles' Day sold over a hundred billion yuan in one day.", "一千二百零七亿。", "¥120.7 billion.")),
            On(20161112, S(2, false, "双十一是国庆节。", "Singles' Day is National Day.", "国庆是十月一日，双十一是购物节。", "National Day is 1 October; 11 November is the shopping festival.")),
            On(20161202, S(2, true, "《你的名字。》是新海诚的动画电影。", "Your Name is an animated film by Makoto Shinkai.", "十二月二号国内上映。", "Out in China on 2 December.")),
            On(20161202, S(2, false, "《你的名字。》是一部国产谍战剧。", "Your Name is a Chinese spy drama.", "是日本动画电影。", "It is a Japanese animated film.")),
            On(20161230, S(3, true, "网上有个叫 Master 的棋手，连赢了好多围棋高手。", "An online player called Master has beaten many top Go players in a row.", "没人知道它是谁。", "Nobody knows who it is.")),
            On(20161230, S(3, false, "Master 把所有围棋高手都输了一遍。", "Master has lost to every top Go player.", "正相反，它一盘没输。", "The opposite: it has not lost a game.")),
        };

        static XgPhrase On(int since, XgPhrase p) { p.since = since; return p; }
    }
}
